mod version;

use async_trait::async_trait;

use version::ShowVersion;

use crate::{
    component::{AzCommand, AzCommandGroup, AzComponentCtx, AzComponentImpl, Versioned},
    error::{AzError, AzInternalError},
    pb::{execute_response, CrsCommandGroup, CrsHelp, CrsInterface, CrsOutputFormat, CrsParams},
    uri::CrsUri,
    VERSION,
};

#[derive(Debug, Default)]
pub struct TopComponent {}

impl Versioned for TopComponent {
    const VERSION: &'static str = VERSION;
}

// will be generated by component macro later
#[async_trait]
impl AzCommandGroup for TopComponent {
    const URI: &'static str = "crs://azure/";

    fn build_interface(depth: Option<u32>) -> CrsCommandGroup {
        let groups = vec![];
        let mut commands = vec![];
        if depth.is_none_or(|d| d > 0) {
            let depth = depth.map(|d| d - 1);
            commands.push(ShowVersion::build_interface(depth));
        }
        CrsCommandGroup {
            name: "".to_string(),
            uri: Self::URI.to_string(),
            help: Some(CrsHelp {
                short: "Contain the top level commands".to_string(),
                long: Some(COMPONENT_LONG_SUMMARY.to_string()),
            }),
            groups,
            commands,
        }
    }

    fn find_interface(
        depth: Option<u32>,
        mut segments: impl Iterator<Item = String>,
    ) -> Option<CrsInterface> {
        match segments.next().as_deref() {
            None => Some(Self::build_interface(depth).into()),
            Some("version") => Some(ShowVersion::build_interface(depth).into()),
            _ => None,
        }
    }

    fn resolve_uri(mut segments: impl Iterator<Item = String>) -> Option<CrsUri> {
        match segments.next().as_deref() {
            None => Some(Self::uri()),
            Some("version") => Some(ShowVersion::uri()),
            _ => None,
        }
    }

    async fn execute_group<T: AzComponentCtx>(
        ctx: &T,
        mut segments: impl Iterator<Item = String> + Send,
        params: Option<CrsParams>,
        output_format: Option<CrsOutputFormat>,
    ) -> Result<execute_response::Data, AzError> {
        match segments.next().as_deref() {
            Some("version") => ShowVersion::execute(ctx, params, output_format).await,
            Some(other) => Err(AzInternalError::InvalidCrsUriError(other.to_string()).into()),
            None => Err(AzInternalError::InvalidCrsUriError(Self::uri().to_string()).into()),
        }
    }
}

const COMPONENT_LONG_SUMMARY: &str = r"
     /\
    /  \    _____   _ _  ___ _
   / /\ \  |_  / | | | \'__/ _\
  / ____ \  / /| |_| | | |  __/
 /_/    \_\/___|\__,_|_|  \___|

 Welcome to the cool new Azure CLIENT TOOL!
";

// should be generated by component macro later
impl<T: AzComponentCtx> AzComponentImpl<T> for TopComponent {}
